contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run takes an arbitrary amount of Ether to forward
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // record owner and c balance before the call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;

        // call go sending `amount` wei; record whether it reverted
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read owner and c balance after the call
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint balanceAfter = address(c).balance;

        // General rule:
        // If the call did not revert then c's balance must be zero afterwards (it forwards funds out),
        // and the owner must remain unchanged. If it reverted, we can't assume balance change,
        // but owner must still remain unchanged (calls that revert don't change state).
        assert(ownerAfter == ownerBefore && (reverted || balanceAfter == 0));
    }

    // allow receiving Ether forwarded from c
    receive() external payable {}
}

